from work import *
id='local168'
init(id,'远程Data Analyst职位发布，job_id','job postings', '''# 独立题解
题目：“Among job postings that specifically have the Data Analyst, require a non-null annual average salary, and are remote, what is the overall average salary when considering only the top three most frequently demanded skills for these positions?”
没有业务文档。岗位类别job_title_short精确Data Analyst，remote映射job_work_from_home=1，薪资字段salary_year_avg IS NOT NULL，不加薪资>0或salary_rate筛选。按job_id定义发布实体；技能需求频率以符合资格岗位中每技能不同job_id数量，技能关联先去重复(job_id,skill_id)，验证job_id、skill_id唯一。
选需求频率前三技能，严格3个，平手skill_id排序。最后“overall average salary”解释为要求至少一个前三技能的不同岗位等权平均，岗位有多个前三技能不重复赋权；不是三个技能平均薪资的等权平均，也不是岗位-技能关联行平均。三者皆有合理阅读空间，后两者实验算出并保留假定。若所有前三同时具备，是更窄AND候选，也实测但不默认。验证排名总体是否应包括无薪岗位，默认明确资格作用于全题。
''')
query(id,"SELECT count(*) rows,count(distinct job_id) ids FROM job_postings_fact WHERE job_title_short='Data Analyst' AND salary_year_avg IS NOT NULL AND job_work_from_home=1",'eligible-keys.json')
query(id,'SELECT count(*) rows,count(distinct skill_id) ids FROM skills_dim','skill-keys.json')
base='''WITH eligible AS (SELECT job_id,salary_year_avg FROM job_postings_fact WHERE job_title_short='Data Analyst' AND salary_year_avg IS NOT NULL AND job_work_from_home=1), links AS (SELECT DISTINCT job_id,skill_id FROM skills_job_dim), frequencies AS (SELECT l.skill_id,count(distinct e.job_id) demand FROM eligible e JOIN links l USING(job_id) GROUP BY l.skill_id), top_skills AS (SELECT skill_id,demand FROM frequencies ORDER BY demand DESC,skill_id LIMIT 3), selected_jobs AS (SELECT e.* FROM eligible e WHERE EXISTS(SELECT 1 FROM links l JOIN top_skills t USING(skill_id) WHERE l.job_id=e.job_id)) '''
query(id,base+'SELECT f.*,s.skills FROM frequencies f JOIN skills_dim s USING(skill_id) ORDER BY demand DESC LIMIT 10','skill-ranking.json')
query(id,base+'SELECT count(*) jobs,avg(salary_year_avg) salary,sum(salary_year_avg) salary_sum FROM selected_jobs','selected-job-average.json')
query(id,base+'SELECT t.skill_id,s.skills,t.demand,count(*) rows,avg(e.salary_year_avg) skill_salary FROM eligible e JOIN links l USING(job_id) JOIN top_skills t USING(skill_id) JOIN skills_dim s USING(skill_id) GROUP BY t.skill_id','per-skill-means.json')
query(id,base+'SELECT count(*) link_rows,avg(e.salary_year_avg) association_average FROM eligible e JOIN links l USING(job_id) JOIN top_skills t USING(skill_id)','association-average.json')
query(id,base+'SELECT n_top_skills,count(*) jobs,avg(salary_year_avg) salary FROM (SELECT e.job_id,e.salary_year_avg,count(t.skill_id) n_top_skills FROM eligible e JOIN links l USING(job_id) JOIN top_skills t USING(skill_id) GROUP BY e.job_id) GROUP BY n_top_skills','salary-multiplicity-distribution.json')
query(id,base+'SELECT count(*) rows,count(distinct j.job_id||\':\'||j.skill_id) unique_links FROM skills_job_dim j JOIN eligible e USING(job_id)','eligible-link-duplicates.json')
fields={'population.eligibility':{'value':'Distinct postings with exact Data Analyst short title, non-null salary_year_avg, remote=1; then require at least one of top3 skills','basis':'assumed','rationale':'Salary is per posting, OR of selected skills; ranking within same eligible cohort'},'population.conditions':{'value':["job_title_short='Data Analyst'",'salary_year_avg IS NOT NULL','job_work_from_home=1'],'basis':'request','quote':'Data Analyst, require a non-null annual average salary, and are remote'},'population.time':'n/a','measure.formula':{'value':{'op':'avg','of':'salary_year_avg'},'basis':'assumed','rationale':'Overall average of distinct jobs requesting any selected skill'},'measure.countGrain':'each distinct job_id exactly once','measure.denominator':'number of distinct eligible jobs requiring at least one selected top3 skill; empty set gives NULL','grouping':'n/a','selection':{'value':{'n':3,'orderBy':'skill demand DESC, skill_id ASC'},'basis':'request','quote':'top three most frequently demanded skills'},'selection.ties':'strict','output':{'value':{'rowMode':'scalar','columns':['overall_average_salary']},'basis':'request','quote':'overall average salary'}}
finish(id,fields,base+'SELECT avg(salary_year_avg) overall_average_salary FROM selected_jobs',{'algorithm':'Rank skills by distinct eligible job count; select jobs requiring any top3; one salary per posting','assumptions':['overall mean is posting-equal not job-skill weighted or skill-equal','OR selected skills','ranking within salary-known remote Data Analyst cohort']});progress(id,'frozen');reveal(id)
